        // Key should be loaded again
        cache.get(TEST_INDEX_UUID, TEST_SHARD_ID, "test-index");

        // Should have loaded twice (once before eviction, once after)
        verify(mockResolver, times(2)).loadKeyFromMasterKeyProvider();
    }

